Spec:
Feature sentence-case: Sentence case a text
Entrypoint: POST /sentence-case
- AC1: POST /sentence-case capitalizes the first letter
- AC2: the rest of the text is lowercased
- AC3: a value that is not a string is rejected with 400

Change:
--- features/sentence-case/index.ts
import { json, type Feature } from "../../shared/http.ts";

export function compute(value: string): string {
  return value.charAt(0).toUpperCase() + value.slice(1);
}

export const feature: Feature = {
  id: "sentence-case",
  title: "Sentence case a text",
  routes: [
    {
      method: "POST",
      path: "/sentence-case",
      handle: async (request) => {
        const body = (await request.json().catch(() => null)) as { value?: unknown } | null;
        if (typeof body?.value !== "string") return json({ error: "value must be a string" }, 400);
        return json({ result: compute(body.value) });
      },
    },
  ],
};

--- features/sentence-case/sentence-case.test.ts
import assert from "node:assert/strict";
import { test } from "node:test";
import { createApp } from "../../shared/http.ts";
import { MemoryStore } from "../../shared/storage.ts";
import { feature } from "../../features/sentence-case/index.ts";

async function call(value: unknown): Promise<{ status: number; result: unknown }> {
  const app = createApp([feature], new MemoryStore());
  const response = await app(new Request("http://app.test/sentence-case", { method: "POST", body: JSON.stringify({ value }), headers: { "content-type": "application/json" } }));
  const body = (await response.json()) as { result?: unknown };
  return { status: response.status, result: body.result };
}

test("AC1: POST /sentence-case capitalizes the first letter", async () => {
  const { status, result } = await call("hello world");
  assert.equal(status, 200);
  assert.deepEqual(result, "Hello world");
});

test("AC2: the rest of the text is lowercased", async () => {
  const { status, result } = await call("abc");
  assert.equal(status, 200);
  assert.deepEqual(result, "Abc");
});

test("AC3: a value that is not a string is rejected with 400", async () => {
  const { status } = await call(42);
  assert.equal(status, 400);
});

